/**
 * Shared wire-shape and identifier helpers used by anything that
 * translates wire data into EDK TypeScript source — both the
 * `defineX.fromJSON` deserializer pipeline and the
 * `fetch-app-definition` renderer that emits standalone
 * `app({...})` files.
 *
 * Helpers that turn out to be useful across more than one of those
 * paths live here so we have a single implementation of each
 * convention (camelCase identifier shape, dedup-with-suffix rule, …)
 * instead of duplicating them per-module and quietly drifting.
 */
/**
 * Returns a shallow copy of the input object with the `type` key
 * removed. Idempotent — no-op if `type` isn't present. Returns `{}`
 * for `undefined` so callers can chain without null checks.
 *
 * **Why this exists.** Wire shapes carry the task / trigger
 * discriminator inline as `properties.type` (SCREAMING_SNAKE):
 *
 * ```
 * properties: { type: "RECORD_SEARCH", aspectId: "...", filter: {...} }
 * ```
 *
 * The deserializer's serializer-input shape carries the
 * discriminator as the *wrapping key* (camelCase) instead:
 *
 * ```
 * { recordSearch: { aspectId: "...", filter: {...} } }
 * ```
 *
 * So normalize wraps via `{ [camelKey]: stripType(props) }` — the
 * wrapping key is the new discriminator, and the previously-inline
 * `type` becomes redundant. Carrying both could confuse downstream
 * code switching on either form, so we drop it.
 */
export declare function stripType(props: {
    readonly [key: string]: unknown;
} | undefined): Record<string, unknown>;
/**
 * Convert a human-readable label into a camelCase JS identifier:
 * `"P1 Critical"` → `"p1Critical"`, `"App Version"` → `"appVersion"`,
 * `"first NAME"` → `"firstName"`. Strips non-alphanumeric characters,
 * collapses runs of separators, lowercases the leading character of
 * the first part and Pascal-cases the rest.
 *
 * Returns `""` for inputs that contain no alphanumerics — callers
 * decide what fallback to use (e.g. `"item1"`).
 */
export declare function camelCase(input: string): string;
/**
 * Mobius's `ValueReference.ofTriggerReference` canonicalizes onDemand
 * parameter reference names so the UI picker can resolve them:
 *   - all alphanumeric       → first char lowercased (`amountUsd` stays
 *                              `amountUsd`, `AmountUsd` → `amountUsd`)
 *   - contains non-alnum char → camelCase via {@link camelCase}
 *                              (`amount_usd` → `amountUsd`,
 *                              `has receipt` → `hasReceipt`)
 *
 * Lives here (not in the serializer) because both sides of the wire
 * need it: the serializer applies it on-write so saved triggerReference
 * names match the picker's canonical form, and the deserializer
 * applies it on-read to map wire reference names back to the source's
 * declared parameter names.
 */
export declare function normalizeOnDemandParamKey(name: string): string;
/**
 * Pair each item with a unique camelCase key derived from
 * `nameOf(item)`. Collisions are disambiguated with numeric suffixes
 * (`foo`, `foo2`, `foo3`, …) so an emitted object literal never has
 * duplicate keys. Source order is preserved.
 *
 * `fallbackPrefix` is used when an item's name camelCases to `""`
 * (e.g. all-punctuation names) — callers pass `"field"` /
 * `"automation"` / etc. so the fallback is self-documenting.
 *
 * Used by both the deserializer's catalog (`pull/catalog.ts`) and the
 * fetch-app-definition renderer (`src/scripts/fetch-app-definition.ts`)
 * so a fetched app file and a pulled entity file disambiguate the
 * same way for the same input.
 */
export declare function withUniqueKeys<T>(items: readonly T[], nameOf: (t: T) => string, fallbackPrefix?: string, handleOf?: (t: T) => string | null | undefined): readonly {
    key: string;
    item: T;
}[];
/**
 * Build the JS identifier used as both the exported variable name
 * and the import binding for an app's generated `.ts` file. The
 * generated file is consumed by other generated files that
 * `import { agentToolPlaygroundApp } from "../apps/agent-tool-playground.js"`,
 * so the binding must be a valid JS identifier.
 *
 * camelCases the app name and appends `App` (idempotently). Two apps
 * whose names happen to camel-case to the same identifier can still
 * be disambiguated downstream by the catalog's per-handle pass.
 */
export declare function handleFromName(name: string): string;
/**
 * Quote a value as a TypeScript string literal — uses
 * `JSON.stringify` so all whitespace, control characters, and
 * non-ASCII code points are escaped to valid TS source. Naming an
 * obvious case to remember why this matters: a field name with an
 * embedded newline would render as an unescaped literal newline
 * inside the emitted `"..."` and break parsing.
 */
export declare function quote(s: string): string;
/**
 * Unwrap a GraphQL `Connection<T>` into a flat readonly array of
 * nodes. Accepts `null | undefined` so callers don't have to
 * distinguish "field not requested" (undefined) from "field
 * explicitly null" (null) — both yield an empty list.
 */
export declare function unwrapConnection<T>(conn: {
    readonly edges?: ReadonlyArray<{
        readonly node: T;
    }>;
} | null | undefined): readonly T[];
export declare function isUuid(value: string): boolean;
/**
 * Format a stage's identity slots as a TypeScript object literal —
 * `{ id, name, color?, icon? }`. `color`/`icon` are omitted when null,
 * undefined, or empty so the catalog (wire-shape) and round-trip
 * (normalized) printers agree on the emitted source.
 */
export declare function formatStageBody(stage: {
    readonly id: string;
    readonly name: string;
    readonly color?: string | null;
    readonly icon?: string | null;
}): string;
